def find_solutions(limit):
    solutions = []
    for n in range(1, limit + 1):
        temp_n = n
        factors = {}
        d = 2
        while d * d <= temp_n:
            while temp_n % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp_n //= d
            d += 1
        if temp_n > 1:
            factors[temp_n] = factors.get(temp_n, 0) + 1

        sum_ai_pi = 0
        for p, a in factors.items():
            sum_ai_pi += a / p

        if abs(sum_ai_pi - 1.0) < 1e-9:
            solutions.append(n)
    return solutions

print(find_solutions(4000))

